class ERC20:
    def __init__(self, name, symbol, decimals, owner, supply):
        self.name, self.symbol, self.decimals = name, symbol, decimals
        self.totalSupply = supply
        self.balances = {owner: supply}
        self.allowances = {}          # (owner, spender) -> amount
        self.events = []

    def balanceOf(self, a):
        return self.balances.get(a, 0)

    def allowance(self, owner, spender):
        return self.allowances.get((owner, spender), 0)

    def _move(self, frm, to, v):
        if self.balanceOf(frm) < v:
            raise ValueError("revert: saldo insufficiente")
        self.balances[frm] = self.balanceOf(frm) - v
        self.balances[to] = self.balanceOf(to) + v
        self.events.append(("Transfer", frm, to, v))

    def transfer(self, sender, to, v):
        self._move(sender, to, v)
        return True

    def approve(self, sender, spender, v):
        self.allowances[(sender, spender)] = v      # sovrascrive
        self.events.append(("Approval", sender, spender, v))
        return True

    def transferFrom(self, sender, frm, to, v):
        if self.allowance(frm, sender) < v:
            raise ValueError("revert: allowance insufficiente")
        self._move(frm, to, v)
        self.allowances[(frm, sender)] -= v
        return True

    def check(self):
        assert sum(self.balances.values()) == self.totalSupply

