from decimal import Decimal, getcontext
getcontext().prec = 80

def to_units(amount: str, decimals: int) -> int:
    """'2.5' token -> intero in unità minime (errore se servono più cifre di decimals)."""
    d = Decimal(amount) * (Decimal(10) ** decimals)
    if d != d.to_integral_value():
        raise ValueError(f"{amount} ha più di {decimals} cifre decimali")
    return int(d)

def to_display(units: int, decimals: int) -> str:
    d = Decimal(units) / (Decimal(10) ** decimals)
    return format(d.normalize(), 'f')

print(to_units("2.5", 18))
print(to_units("2.5", 6))
print(to_display(1500000000000000000, 18))
print(to_display(12345, 2))
print("_mint(msg.sender, 1000) con 18 decimali =", to_display(1000, 18), "token")
print("100_000 * 10**18 =", 100_000 * 10**18)
try:
    to_units("0.0000001", 6)
except ValueError as e:
    print("errore:", e)

