UINT_MAX = 2**256 - 1

def checked_sub(a, b):          # aritmetica controllata di Solidity >= 0.8
    if b > a:
        raise ArithmeticError("revert: underflow")
    return a - b

def checked_add(a, b):
    if a + b > UINT_MAX:
        raise ArithmeticError("revert: overflow")
    return a + b

def transferFrom_slide(bal, allw, sender, frm, to, v):
    """Versione della slide 44 (segni invertiti)."""
    bal, allw = dict(bal), dict(allw)          # copia: revert = nessun effetto
    assert allw.get((frm, sender), 0) >= v, "revert: require"
    bal[frm] = checked_add(bal.get(frm, 0), v)
    bal[to] = checked_sub(bal.get(to, 0), v)
    allw[(frm, sender)] = checked_sub(allw[(frm, sender)], v)
    return bal, allw

def transferFrom_ok(bal, allw, sender, frm, to, v):
    bal, allw = dict(bal), dict(allw)
    assert allw.get((frm, sender), 0) >= v, "revert: require"
    bal[frm] = checked_sub(bal.get(frm, 0), v)
    bal[to] = checked_add(bal.get(to, 0), v)
    allw[(frm, sender)] -= v
    return bal, allw

allw = {("A", "B"): 100}
for bal in ({"A": 1000, "B": 0}, {"A": 1000, "B": 200}):
    print("stato iniziale", bal)
    for f in (transferFrom_slide, transferFrom_ok):
        try:
            nb, na = f(bal, allw, "B", "A", "B", 50)
            print(f"  {f.__name__:19s} -> {nb}  allowance={na[('A','B')]}")
        except ArithmeticError as e:
            print(f"  {f.__name__:19s} -> {e}")

